import{_ as l,o as s,c as t,ah as a}from"./chunks/framework.ChH6X6u6.js";const b=JSON.parse('{"title":"Bulletins","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/bulletins.md","filePath":"src/guide/admin/bulletins.md"}'),i={name:"guide/admin/bulletins.md"};function r(n,e,u,o,d,c){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="bulletins" tabindex="-1">Bulletins <a class="header-anchor" href="#bulletins" aria-label="Permalink to &quot;Bulletins&quot;">​</a></h1><p>Cette page couvre la publication des bulletins côté administration — une fois que les enseignants ont saisi leurs notes et appréciations pour une période donnée (ce qui est leur propre travail, pas le vôtre), c&#39;est vous qui déclenchez la génération et la mise à disposition des bulletins.</p><h2 id="publier-les-bulletins-d-une-classe" tabindex="-1">Publier les bulletins d&#39;une classe <a class="header-anchor" href="#publier-les-bulletins-d-une-classe" aria-label="Permalink to &quot;Publier les bulletins d&#39;une classe&quot;">​</a></h2><p>Depuis <strong>Paramétrage scolaire → Classes</strong>, cliquez sur <strong>Bulletins</strong> sur la ligne de la classe concernée.</p><p>Pour publier :</p><ol><li>Choisissez la <strong>Période scolaire</strong> concernée dans le menu déroulant en haut de la page.</li><li>Cliquez sur <strong>Publier / republier les bulletins</strong>.</li></ol><p>Cela génère (ou régénère) le bulletin de chaque élève de la classe pour cette période, à partir des notes et appréciations déjà saisies. Republier après une correction de note met à jour le bulletin déjà publié — les élèves et parents voient toujours la dernière version.</p><p>Si aucune période scolaire n&#39;est configurée pour l&#39;année de cette classe, un message vous l&#39;indique — allez d&#39;abord créer une période dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</p><h2 id="suivre-et-telecharger-les-bulletins" tabindex="-1">Suivre et télécharger les bulletins <a class="header-anchor" href="#suivre-et-telecharger-les-bulletins" aria-label="Permalink to &quot;Suivre et télécharger les bulletins&quot;">​</a></h2><p>Le tableau sous le sélecteur de période liste chaque élève de la classe avec :</p><ul><li><strong>Statut</strong> — « Non publié », ou la date de publication du bulletin.</li><li>Un bouton de téléchargement (icône), disponible dès qu&#39;un bulletin a été généré pour cet élève.</li></ul><h2 id="modele-de-bulletin" tabindex="-1">Modèle de bulletin <a class="header-anchor" href="#modele-de-bulletin" aria-label="Permalink to &quot;Modèle de bulletin&quot;">​</a></h2><p>Le modèle visuel utilisé (Classique, Compact ou Traditionnel à la française) se choisit par classe, dans le formulaire de la classe — voir <a href="/era-guide/guide/admin/structure-etablissement.html#classes">Structure de l&#39;établissement</a>. Si aucun modèle n&#39;est choisi pour une classe, le modèle par défaut de l&#39;établissement s&#39;applique.</p>',13)])])}const h=l(i,[["render",r]]);export{b as __pageData,h as default};
